    (386::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-11-08T00:00:00+00:00'::TIMESTAMPTZ, '0ea821c1f342c1eed4d263dd001f40989e30d3d373d8d8e5efa1124dc10de6be'::TEXT, ARRAY[1252]::BIGINT[]),
    (386::BIGINT, 'En los exámenes salen problemas casi idénticos a los vistos en clase entonces se hacen fácilmente. Solo hace dos exámenes y nunca entrega el segundo entonces uno se queda preocupado si pasó o no hasta que entreguen actas, aunque al final la gran mayoría pasa bien.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'a85e385be1b792ec8c0c1aa376fd8804205f5bc0ef92ff4094dfa67f4e453d6c'::TEXT, ARRAY[1276]::BIGINT[]),
    (386::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, 'a2a22a9335f3a793f74bde17ecbcf69edb99126a473a6499057b325ce35703cc'::TEXT, ARRAY[1252]::BIGINT[]),
    (386::BIGINT, 'Lo que se ve en clase es literalmente lo que sale en el examén, devuelve el primer examen pero el segundo no, uno sabe si paso ya cuando entregan actas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-28T00:00:00+00:00'::TIMESTAMPTZ, '9b8e7048065267d7ecef6963b2e7ad3a329f45a6af1d5421c0b1fc5d7dfa4076'::TEXT, ARRAY[1276]::BIGINT[]),
    (386::BIGINT, 'Discretos no es fácil, pero el mae hace el curso muy pasable. Es un poco vago, pero lo que explica lo hace bien y depende de uno estudiar como se debe. PD. Los problemas vistos en clase salen IGUALES en el examen.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '8bb12be50d566b228421f0459d4e48e95f24a03f83a0b01f7cc07688be72a1f6'::TEXT, ARRAY[1276]::BIGINT[]),
    (386::BIGINT, 'sus clases son interesantes, deja proyectos chivas y consejos de vida buenos jajaja, vale la pena llevar el curso con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '59e86ddf98e792877d4690f3d84c4ba7b4ea957f4fa672458d0be1d31f589fdf'::TEXT, ARRAY[1252]::BIGINT[]),
    (386::BIGINT, 'Hay como tres W. Marín en mis profes XD. Es un profesor pura vida y buena persona pero calificando es un misterio a final del semestre. Tenes que pasar el primer examen y prepararte para el segundo que es un toque más complejo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, '9bc0c6b5eba2bb4250f593995ab0262117069da2019a3ad0319b46f2ad98c563'::TEXT, ARRAY[1276]::BIGINT[]),
    (386::BIGINT, 'El profe es buena gente, pero muy vago, falta bastante a clases. Igual va pasar a el curso .'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes', 'Pocos exámenes']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, '38d5ca6d46b67f201df62c86941ba25065b40fd84276faa625159bdfb946794a'::TEXT, ARRAY[1294]::BIGINT[]),
    (386::BIGINT, 'Al inicio el curso es aburrido por los proyectos que son como los de la escuela, pero al final se puso teja porque se aprende lo básico de la rasberry..yo quiero una!!!!! Jajajaj, recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'bfd8bc45ad21a89e0e29fe50ca3e7693b9e711d374c8dd6d6fb49456c83ae558'::TEXT, ARRAY[1252]::BIGINT[]),
