    (386::BIGINT, 'A estas alturas de la carrera uno puede estudiar sólo. El profe lo guía..todop pura vida'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-04-26T00:00:00+00:00'::TIMESTAMPTZ, '45c2d0008a5259731171de5b797a81b6ebeb517cceeacd83e5274ecd0b12da4a'::TEXT, ARRAY[1323, 1325, 1404]::BIGINT[]),
    (386::BIGINT, 'Bueno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2018-03-11T00:00:00+00:00'::TIMESTAMPTZ, '48a02ed5daa4fa718a44443255ad23d70695c9f11921fb9e1c2e073a79596e8d'::TEXT, ARRAY[1294]::BIGINT[]),
    (386::BIGINT, 'Bueno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2018-01-18T00:00:00+00:00'::TIMESTAMPTZ, '14be5461bb8a78f5d060952cd222816ce95d349047029180d3f0d0cd4db9f9d9'::TEXT, ARRAY[1276]::BIGINT[]),
    (386::BIGINT, 'Buen curso y bien profesor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2017-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'd9754e009a8b8c25156e53546dbde7915e507614cdf02faa4db7d4ed43aeeb32'::TEXT, ARRAY[1276]::BIGINT[]),
    (386::BIGINT, 'Literalmente le debo el trabajo al profe Marín. Instalé un DHCP, Apache, Proxy y Firewall exactamente como se vio en clase en una empresa y quedé contratado. Dice mi jefe que nunca había estado la red tan estable y rápida (al administrador anterior lo echaron por eso). Ponga atención en clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2017-12-05T00:00:00+00:00'::TIMESTAMPTZ, '4a0a1cc200886b11a029cb8715dc48c269f7d6f74ebc03b1a385e38f5845b3c5'::TEXT, ARRAY[3791]::BIGINT[]),
    (386::BIGINT, 'No hagan caso de los comentarios anteriores, me pareció buen profe, si usted estudia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2017-12-05T00:00:00+00:00'::TIMESTAMPTZ, '21ce5dd6b07213771fae4427454cdccba2d93c2672ccaa3fb6538c7068c7381b'::TEXT, ARRAY[1276]::BIGINT[]),
    (386::BIGINT, 'Buen profe cuando explica lo hace bien se le entiende y se ve que se preocupa por el estudiantes lo malo es que es muy vago y falta mucho a clases pero en general es buen profe y muy pura vida'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-10T00:00:00+00:00'::TIMESTAMPTZ, '13b648a845d25c20e3767be63d21a177b483fcb8473bd399e74912a091fa9f57'::TEXT, ARRAY[1276]::BIGINT[]),
    (386::BIGINT, 'Buena nota, algunas veces se complica pero ayuda en consulta hasta de otros cursos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2017-11-06T00:00:00+00:00'::TIMESTAMPTZ, '65b70a7a4bbd998e17b991b7cbde2a654a1946e696be885e89d973e8391888b5'::TEXT, ARRAY[1276]::BIGINT[]),
    (386::BIGINT, 'solo bueno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2017-09-18T00:00:00+00:00'::TIMESTAMPTZ, 'ea2a70f738b5fc976a8a162d6f2f9ad7fa348a796727d49f0b1b041226cb4290'::TEXT, ARRAY[1256, 1261]::BIGINT[]),
    (386::BIGINT, 'Estudiebastante del libro,y vaya a consulta'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2017-08-18T00:00:00+00:00'::TIMESTAMPTZ, '49a8fe668e04c87d74d7cd5d5753cd621543da71e3a7452e359b0376dbfd7bba'::TEXT, ARRAY[1276]::BIGINT[]),
    (386::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2017-08-10T00:00:00+00:00'::TIMESTAMPTZ, '760c2343034b48f15e9f62cbdeec62f44f4ab1ce5c28258adc639517138fb9f5'::TEXT, ARRAY[1261]::BIGINT[]),
    (386::BIGINT, 'El curso es Rudísimo, y Marín se esfuerza por que uno entienda de dónde diablos salen las cosas. Hay que practicar un leñazo, pero se aprende mucho'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Exámenes retadores']::TEXT[], '2017-08-06T00:00:00+00:00'::TIMESTAMPTZ, '2b386aedd58e29e5c9bd9df439764d761579990403218d9ccb2f7e755770212e'::TEXT, ARRAY[1163]::BIGINT[]),
    (386::BIGINT, 'Sabe usar los instrumentos y no es como otros que sólo teoría saben'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2017-08-03T00:00:00+00:00'::TIMESTAMPTZ, 'aacf95a97b63f22cb7364efffa1bbb0ec0d8330689c2ebac7e79016de8bebfbd'::TEXT, ARRAY[1281]::BIGINT[]),
    (386::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Da crédito extra']::TEXT[], '2017-08-03T00:00:00+00:00'::TIMESTAMPTZ, 'a240247d1296ee4857675c1d523b19899e42547d5003d757e033cebebb1e64df'::TEXT, ARRAY[1256, 1261]::BIGINT[]),
    (386::BIGINT, 'Hay que agarrarle el toque, explica bien y aunque sea de otros cursos el mae ayuda en consultas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2017-08-03T00:00:00+00:00'::TIMESTAMPTZ, '1262cc45a4488ab7d1c17bd9d13fdf39b117046583e5508a72bc2e52d3b6b9dc'::TEXT, ARRAY[1281]::BIGINT[]),
    (386::BIGINT, 'Nunca entregó los informes y casi apuesto que no los leyó. Nunca estaba en el aula, apenas llegaba a abrir y se iba. No aclara dudas. A pesar de que uno pasa el curso con buena nota no se aprende nada. La única forma de aprender es investigar y hacer los informes a conciencia.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '476912f0f738d9a161c16c3050af09fdc8aa4af2db53ee6853fba31c88de7d9d'::TEXT, ARRAY[1281]::BIGINT[]),
    (386::BIGINT, 'No entrego ni un solo informe, además de exigir informes casi semanales pide bitácora al final del semestre. Explica lo necesario. Si necesita ayuda se la da, pero a veces ni siquiera está en el aula. Se aprende muy poco. Tampoco siento que sea la peor opcion para el curso.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b3b9b967a9b1fbff013b2bd23d4805e472a2b83e5f26a3b48e9b9712622bac32'::TEXT, ARRAY[927]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
